edges = []
for u in range(7):
    for v in range(7, 14):
        edges.append([u, v])

# Verify it's triangle-free
def is_triangle_free(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

# Verify it's maximal
def is_maximal(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in range(i + 1, n):
            if j not in adj[i]:
                # Check if adding (i, j) creates a triangle
                # A triangle is created if there exists a vertex k such that (i, k) and (j, k) are edges
                creates_triangle = False
                for k in range(n):
                    if k in adj[i] and k in adj[j]:
                        creates_triangle = True
                        break
                if not creates_triangle:
                    return False, (i, j)
    return True, None

print(f"Is triangle-free: {is_triangle_free(14, edges)}")
maximal, edge = is_maximal(14, edges)
print(f"Is maximal: {maximal}, {edge}")
print(f"Number of edges: {len(edges)}")
